<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../helpers/auth.php'; require_once __DIR__.'/../helpers/escape.php';
$page = $_GET['page'] ?? (empty($_SESSION['user']) ? 'login' : 'dashboard');
$publicPages=['login','setup','seed_admin']; if (!in_array($page,$publicPages,true)) require_login();
if ($_SERVER['REQUEST_METHOD']==='POST') verify_csrf();
$flash=$_SESSION['flash']??''; unset($_SESSION['flash']);
function go(string $page): never { header('Location: index.php?page='.$page); exit; }
function flash(string $message): void { $_SESSION['flash']=$message; }
function poststr(string $key): string { return trim((string)($_POST[$key] ?? '')); }

if ($page==='login' && $_SERVER['REQUEST_METHOD']==='POST') {
 $stmt=$pdo->prepare('SELECT id,username,password_hash,full_name,role FROM users WHERE username=:u'); $stmt->execute(['u'=>poststr('username')]); $u=$stmt->fetch();
 if ($u && password_verify((string)($_POST['password']??''),$u['password_hash'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$u['id'],'username'=>$u['username'],'full_name'=>$u['full_name'],'role'=>$u['role']]; go('dashboard'); }
 $flash='Username atau password salah.';
}
if ($page==='logout') { $_SESSION=[]; session_destroy(); header('Location: index.php?page=login'); exit; }

if ($page==='seed_admin' && $_SERVER['REQUEST_METHOD']==='POST') {
 if ((int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn() > 0) { flash('Akun admin sudah tersedia. Silakan login.'); go('login'); }
 $username=poststr('username'); $name=poststr('full_name'); $password=(string)($_POST['password']??'');
 if (strlen($password)<8 || $username==='' || $name==='') $flash='Isi semua kolom. Password minimal 8 karakter.';
 else { try { $s=$pdo->prepare("INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?,'admin')"); $s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$name]); flash('Akun admin berhasil dibuat. Silakan login.'); go('login'); } catch(Throwable $e) { $flash='Gagal membuat akun. Username mungkin sudah digunakan.'; } }
}

// Semua perubahan data menggunakan POST + CSRF, prepared statement dan validasi server.
if ($page==='category_save' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin(); $id=(int)($_POST['id']??0); $name=poststr('name'); $desc=poststr('description'); if($name==='') $flash='Nama kategori wajib diisi.'; else { try { if($id){$s=$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->execute([$name,$desc,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->execute([$name,$desc]);} $flash='Kategori disimpan.';}catch(Throwable $e){$flash='Kategori gagal disimpan. Pastikan nama tidak duplikat.';} } go('categories'); }
if ($page==='category_delete' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin(); try{$s=$pdo->prepare('DELETE FROM categories WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Kategori dihapus.');}catch(Throwable $e){flash('Kategori tidak dapat dihapus karena masih digunakan produk.');}go('categories'); }
if ($page==='product_save' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin(); $id=(int)($_POST['id']??0);$cat=(int)($_POST['category_id']??0);$sku=strtoupper(poststr('sku'));$name=poststr('name');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$min=filter_var($_POST['minimum_stock']??null,FILTER_VALIDATE_INT);$supplierIds=array_map('intval',$_POST['suppliers']??[]); if(!$cat||$sku===''||$name===''||$price===false||$price<0||$min===false||$min<0){flash('Periksa kembali SKU, nama, kategori, harga, dan stok minimum.');go('products');} try{$pdo->beginTransaction();if($id){$s=$pdo->prepare('UPDATE products SET category_id=?,sku=?,name=?,price=?,minimum_stock=? WHERE id=?');$s->execute([$cat,$sku,$name,$price,$min,$id]);}else{$s=$pdo->prepare('INSERT INTO products(category_id,sku,name,price,stock,minimum_stock) VALUES(?,?,?,?,0,?)');$s->execute([$cat,$sku,$name,$price,$min]);$id=(int)$pdo->lastInsertId();}$pdo->prepare('DELETE FROM product_suppliers WHERE product_id=?')->execute([$id]);$ps=$pdo->prepare('INSERT INTO product_suppliers(product_id,supplier_id,supplier_price) VALUES(?,?,?)');foreach(array_unique($supplierIds) as $sid){$ps->execute([$id,$sid,$price]);}$pdo->commit();flash('Produk berhasil disimpan.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Produk gagal disimpan. Periksa SKU unik dan kategori/supplier.');}go('products'); }
if ($page==='product_delete' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin();try{$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Produk dihapus.');}catch(Throwable $e){flash('Produk tidak dapat dihapus karena sudah memiliki histori transaksi.');}go('products'); }
if ($page==='supplier_save' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin();$id=(int)($_POST['id']??0);$name=poststr('name');$phone=poststr('phone');$email=poststr('email');$address=poststr('address');if($name==='')$flash='Nama supplier wajib diisi.';else{if($id){$s=$pdo->prepare('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?');$s->execute([$name,$phone,$email,$address,$id]);}else{$s=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$s->execute([$name,$phone,$email,$address]);}$flash='Supplier disimpan.';}go('suppliers'); }
if ($page==='supplier_delete' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin();try{$pdo->prepare('DELETE FROM suppliers WHERE id=?')->execute([(int)$_POST['id']]);flash('Supplier dihapus.');}catch(Throwable $e){flash('Supplier tidak dapat dihapus karena masih terhubung dengan produk.');}go('suppliers'); }
if ($page==='movement_save' && $_SERVER['REQUEST_METHOD']==='POST') { $pid=(int)($_POST['product_id']??0);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$type=($_POST['type']??'')==='OUT'?'OUT':'IN';$note=poststr('note');if(!$pid||$qty===false||$qty<=0){flash('Produk dan jumlah positif wajib diisi.');go('stock');}try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$s->execute([$pid]);$p=$s->fetch();if(!$p)throw new RuntimeException('Produk tidak ditemukan.');if($type==='OUT' && $qty>(int)$p['stock'])throw new RuntimeException('Stok tidak cukup. Transaksi dibatalkan.');$delta=$type==='IN'?$qty:-$qty;$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$delta,$pid]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)')->execute([$pid,$_SESSION['user']['id'],$type,$qty,$note]);$pdo->commit();flash('Transaksi stok berhasil dicatat.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Transaksi gagal dan telah dibatalkan.');}go('stock'); }
if ($page==='user_save' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin();$id=(int)($_POST['id']??0);$username=poststr('username');$name=poststr('full_name');$role=($_POST['role']??'staff')==='admin'?'admin':'staff';$pass=(string)($_POST['password']??'');if(!$id&&strlen($pass)<8){flash('Password awal minimal 8 karakter.');go('users');}try{if($id){if($pass!==''){$s=$pdo->prepare('UPDATE users SET username=?,full_name=?,role=?,password_hash=? WHERE id=?');$s->execute([$username,$name,$role,password_hash($pass,PASSWORD_DEFAULT),$id]);}else{$s=$pdo->prepare('UPDATE users SET username=?,full_name=?,role=? WHERE id=?');$s->execute([$username,$name,$role,$id]);}}else{$s=$pdo->prepare('INSERT INTO users(username,full_name,role,password_hash) VALUES(?,?,?,?)');$s->execute([$username,$name,$role,password_hash($pass,PASSWORD_DEFAULT)]);}flash('Data pengguna disimpan.');}catch(Throwable $e){flash('Gagal menyimpan pengguna. Username mungkin sudah digunakan.');}go('users'); }
if ($page==='user_delete' && $_SERVER['REQUEST_METHOD']==='POST') { require_admin();$id=(int)$_POST['id'];if($id===$_SESSION['user']['id'])flash('Anda tidak dapat menghapus akun yang sedang digunakan.');else{try{$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('Pengguna dihapus.');}catch(Throwable $e){flash('Pengguna memiliki histori transaksi sehingga tidak dapat dihapus.');}}go('users'); }

$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$suppliers=$pdo->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();
function layoutStart(string $title,string $page,string $flash): void { $u=$_SESSION['user']??null; echo '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' · Stockwise</title><link rel="stylesheet" href="assets/style.css"></head><body>'; if($u){echo '<aside class="sidebar"><a class="brand" href="index.php?page=dashboard"><span class="brand-icon">S</span><span>Stockwise<small>INVENTORY SYSTEM</small></span></a><div class="nav-label">MENU UTAMA</div>'; $links=['dashboard'=>'▦|Dashboard','products'=>'▣|Produk','categories'=>'◫|Kategori','suppliers'=>'♧|Supplier','stock'=>'↕|Barang Masuk/Keluar','reports'=>'▤|Laporan']; foreach($links as $k=>$v){[$ico,$label]=explode('|',$v);echo '<a class="nav-link '.($page===$k?'active':''). '" href="index.php?page='.$k.'"><span>'.$ico.'</span>'.$label.'</a>';}if(is_admin())echo '<div class="nav-label">PENGELOLAAN</div><a class="nav-link '.($page==='users'?'active':'').'" href="index.php?page=users"><span>♙</span>Pengguna</a>';echo '<div class="sidebar-bottom"><div class="avatar">'.e(strtoupper(substr($u['full_name'],0,1))).'</div><div class="user-mini"><b>'.e($u['full_name']).'</b><small>'.e(ucfirst($u['role'])).'</small></div><a class="logout" title="Keluar" href="index.php?page=logout">↗</a></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">INVENTORY MANAGEMENT</span><h1>'.e($title).'</h1></div><div class="top-user"><span class="status-dot"></span> Sistem aktif <span class="top-avatar">'.e(strtoupper(substr($u['full_name'],0,1))).'</span></div></header>';if($flash!=='')echo '<div class="alert">'.e($flash).'</div>'; } else { echo '<main class="login-shell">';if($flash!=='')echo '<div class="alert">'.e($flash).'</div>'; } }
function layoutEnd(): void { echo '</main></body></html>'; }
function tableEmpty(int $span,string $msg='Belum ada data.'): void { echo '<tr><td colspan="'.$span.'" class="empty">'.e($msg).'</td></tr>'; }

if ($page==='login') { layoutStart('Masuk ke akun','login',$flash); echo '<section class="login-card"><div class="login-logo">S</div><span class="eyebrow">SELAMAT DATANG KEMBALI</span><h1>Kelola stok dengan lebih mudah.</h1><p>Masuk untuk mengakses dashboard inventory toko Anda.</p><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><label>Username</label><input name="username" autocomplete="username" required placeholder="Masukkan username"><label>Password</label><input type="password" name="password" autocomplete="current-password" required placeholder="Masukkan password"><button class="btn primary full">Masuk ke Dashboard <span>→</span></button></form><div class="login-foot">Belum ada akun admin? <a href="index.php?page=setup">Buat akun admin</a></div></section>'; layoutEnd(); exit; }
if ($page==='setup') { layoutStart('Buat admin','setup',$flash); echo '<section class="login-card"><div class="login-logo">S</div><h1>Buat akun admin pertama</h1><p>Gunakan halaman ini hanya saat instalasi awal.</p><form method="post" action="index.php?page=seed_admin"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><label>Nama lengkap</label><input name="full_name" required><label>Username</label><input name="username" required><label>Password (min. 8 karakter)</label><input type="password" name="password" minlength="8" required><button class="btn primary full">Buat akun</button></form><div class="login-foot"><a href="index.php?page=login">Kembali ke login</a></div></section>';layoutEnd();exit; }

if ($page==='dashboard') { $stats=$pdo->query("SELECT COUNT(*) total_products,COALESCE(SUM(stock*price),0) inventory_value,COALESCE(SUM(stock),0) total_stock,SUM(stock<=minimum_stock) low_stock FROM products")->fetch();$ins=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='IN' AND DATE(created_at)=CURDATE()")->fetchColumn();$outs=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='OUT' AND DATE(created_at)=CURDATE()")->fetchColumn();$low=$pdo->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.stock<=p.minimum_stock ORDER BY p.stock ASC LIMIT 6')->fetchAll();$recent=$pdo->query('SELECT sm.*,p.name product,p.sku,u.full_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN users u ON u.id=sm.user_id ORDER BY sm.created_at DESC LIMIT 6')->fetchAll();layoutStart('Dashboard','dashboard',$flash);echo '<div class="welcome"><div><span class="eyebrow light">RINGKASAN INVENTORY</span><h2>Halo, '.e($_SESSION['user']['full_name']).' 👋</h2><p>Pantau stok dan aktivitas persediaan toko Anda hari ini.</p></div><a class="btn white" href="index.php?page=stock">＋ Catat transaksi</a></div><div class="stats-grid"><article class="stat-card"><div class="stat-icon purple">▣</div><span>Total Produk</span><strong>'.number_format((int)$stats['total_products']).'</strong><small>Produk terdaftar</small></article><article class="stat-card"><div class="stat-icon green">◈</div><span>Nilai Inventory</span><strong class="money">'.rupiah($stats['inventory_value']).'</strong><small>Nilai stok saat ini</small></article><article class="stat-card"><div class="stat-icon orange">⚠</div><span>Stok Rendah</span><strong>'.number_format((int)$stats['low_stock']).'</strong><small>Perlu segera diperiksa</small></article><article class="stat-card"><div class="stat-icon blue">▤</div><span>Total Unit Stok</span><strong>'.number_format((int)$stats['total_stock']).'</strong><small>Barang tersedia</small></article></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h3>Produk stok rendah</h3><p>Produk dengan stok ≤ batas minimum</p></div><a class="text-link" href="index.php?page=products&low=1">Lihat semua →</a></div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Kategori</th><th>Stok</th><th>Status</th></tr></thead><tbody>';foreach($low as $p)echo '<tr><td><b>'.e($p['name']).'</b><small class="subline">'.e($p['sku']).'</small></td><td>'.e($p['category']).'</td><td><b>'.(int)$p['stock'].'</b><small class="subline">Min. '.(int)$p['minimum_stock'].'</small></td><td><span class="pill danger">Stok rendah</span></td></tr>';if(!$low)tableEmpty(4,'Semua stok berada di atas batas minimum.');echo '</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Aktivitas terbaru</h3><p>Pergerakan stok terakhir</p></div><a class="text-link" href="index.php?page=reports">Laporan →</a></div><div class="activity-list">';foreach($recent as $r)echo '<div class="activity"><span class="movement-icon '.($r['type']==='IN'?'in':'out').'">'.($r['type']==='IN'?'↓':'↑').'</span><div class="activity-info"><b>'.e($r['product']).'</b><small>'.e($r['full_name']).' · '.date('d M H:i',strtotime($r['created_at'])).'</small></div><strong class="'.($r['type']==='IN'?'positive':'negative').'">'.($r['type']==='IN'?'+':'−').(int)$r['quantity'].'</strong></div>';if(!$recent)echo '<div class="empty">Belum ada transaksi stok.</div>';echo '</div></section></div>';layoutEnd();exit; }

if ($page==='products') { $q=trim($_GET['q']??'');$cat=(int)($_GET['category_id']??0);$low=isset($_GET['low']);$sort=$_GET['sort']??'name';$dir=strtoupper($_GET['dir']??'ASC');$allowed=['name'=>'p.name','price'=>'p.price','stock'=>'p.stock','sku'=>'p.sku'];$order=$allowed[$sort]??'p.name';$dir=$dir==='DESC'?'DESC':'ASC';$where=[];$params=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($cat){$where[]='p.category_id=?';$params[]=$cat;}if($low)$where[]='p.stock<=p.minimum_stock';$w=$where?'WHERE '.implode(' AND ',$where):'';$count=$pdo->prepare("SELECT COUNT(*) FROM products p $w");$count->execute($params);$total=(int)$count->fetchColumn();$per=10;$pg=max(1,(int)($_GET['p']??1));$pages=max(1,(int)ceil($total/$per));$pg=min($pg,$pages);$s=$pdo->prepare("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id $w ORDER BY $order $dir LIMIT $per OFFSET ".(($pg-1)*$per));$s->execute($params);$rows=$s->fetchAll();$edit=null;if(isset($_GET['edit'])&&is_admin()){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}layoutStart('Produk','products',$flash);echo '<div class="page-actions"><div><h2>Daftar Produk</h2><p>Kelola SKU, kategori, harga, dan jumlah stok.</p></div>';if(is_admin())echo '<a class="btn primary" href="index.php?page=products&add=1">＋ Tambah produk</a>';echo '</div>';if(is_admin()&&(isset($_GET['add'])||$edit)){echo '<section class="panel form-panel"><div class="panel-head"><div><h3>'.($edit?'Edit produk':'Tambah produk baru').'</h3><p>Stok hanya berubah melalui transaksi barang masuk/keluar.</p></div><a class="close-link" href="index.php?page=products">✕</a></div><form class="form-grid" method="post" action="index.php?page=product_save"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div><label>SKU *</label><input name="sku" required maxlength="50" value="'.e($edit['sku']??'').'" placeholder="Contoh: ELK-003"></div><div><label>Nama produk *</label><input name="name" required maxlength="150" value="'.e($edit['name']??'').'" placeholder="Nama produk"></div><div><label>Kategori *</label><select name="category_id" required><option value="">Pilih kategori</option>';foreach($categories as $c)echo '<option value="'.(int)$c['id'].'" '.((int)($edit['category_id']??0)===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div><div><label>Harga (Rp) *</label><input type="number" name="price" min="0" step="0.01" required value="'.e($edit['price']??'0').'" placeholder="0"></div><div><label>Stok minimum *</label><input type="number" name="minimum_stock" min="0" required value="'.e($edit['minimum_stock']??5).'"></div><div><label>Supplier (bisa lebih dari satu)</label><select name="suppliers[]" multiple size="3">';$selected=[];if($edit){$ss=$pdo->prepare('SELECT supplier_id FROM product_suppliers WHERE product_id=?');$ss->execute([$edit['id']]);$selected=array_map('intval',array_column($ss->fetchAll(),'supplier_id'));}foreach($suppliers as $sp)echo '<option value="'.(int)$sp['id'].'" '.(in_array((int)$sp['id'],$selected,true)?'selected':'').'>'.e($sp['name']).'</option>';echo '</select></div><div class="form-actions"><button class="btn primary">Simpan produk</button><a class="btn ghost" href="index.php?page=products">Batal</a></div></form></section>';}echo '<section class="panel"><form class="filterbar" method="get"><input type="hidden" name="page" value="products"><div class="searchbox"><span>⌕</span><input name="q" value="'.e($q).'" placeholder="Cari nama produk atau SKU..."></div><select name="category_id"><option value="0">Semua kategori</option>';foreach($categories as $c)echo '<option value="'.(int)$c['id'].'" '.($cat===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select><select name="sort"><option value="name">Urut nama</option><option value="price" '.($sort==='price'?'selected':'').'>Urut harga</option><option value="stock" '.($sort==='stock'?'selected':'').'>Urut stok</option><option value="sku" '.($sort==='sku'?'selected':'').'>Urut SKU</option></select><select name="dir"><option '.($dir==='ASC'?'selected':'').' value="ASC">Naik</option><option '.($dir==='DESC'?'selected':'').' value="DESC">Turun</option></select><button class="btn dark">Terapkan</button>';if($low)echo '<input type="hidden" name="low" value="1">';echo '</form><div class="table-wrap"><table><thead><tr><th>Produk / SKU</th><th>Kategori</th><th>Harga</th><th>Stok tersedia</th><th>Status</th>';if(is_admin())echo '<th>Aksi</th>';echo '</tr></thead><tbody>';foreach($rows as $p){$isLow=(int)$p['stock']<=(int)$p['minimum_stock'];echo '<tr><td><b>'.e($p['name']).'</b><small class="subline">'.e($p['sku']).'</small></td><td>'.e($p['category']).'</td><td>'.rupiah($p['price']).'</td><td><b>'.(int)$p['stock'].'</b><small class="subline">Min. '.(int)$p['minimum_stock'].'</small></td><td><span class="pill '.($isLow?'danger':'success').'">'.($isLow?'Stok rendah':'Tersedia').'</span></td>';if(is_admin())echo '<td><div class="actions"><a class="icon-btn" title="Edit" href="index.php?page=products&edit='.(int)$p['id'].'">✎</a><form method="post" action="index.php?page=product_delete" onsubmit="return confirm(\'Hapus produk ini?\')"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)$p['id'].'"><button class="icon-btn danger-text" title="Hapus">⌫</button></form></div></td>';echo '</tr>';}if(!$rows)tableEmpty(is_admin()?6:5,'Produk tidak ditemukan.');echo '</tbody></table></div><div class="table-foot"><span>Menampilkan '.($total?($pg-1)*$per+1:0).'–'.min($pg*$per,$total).' dari '.$total.' produk</span><div class="pagination">';for($i=1;$i<=$pages;$i++){if($i===1||$i===$pages||abs($i-$pg)<=1){$query=$_GET;$query['p']=$i;echo '<a class="'.($i===$pg?'current':'').'" href="?'.e(http_build_query($query)).'">'.$i.'</a>';}}echo '</div></div></section>';layoutEnd();exit; }

if ($page==='categories') {require_login();$rows=$pdo->query('SELECT c.*,COUNT(p.id) total_products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$edit=null;if(isset($_GET['edit'])&&is_admin()){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}layoutStart('Kategori','categories',$flash);echo '<div class="page-actions"><div><h2>Kategori Produk</h2><p>Kelompokkan produk agar lebih mudah dicari.</p></div>';if(is_admin())echo '<a class="btn primary" href="?page=categories&add=1">＋ Tambah kategori</a>';echo '</div>';if(is_admin()&&(isset($_GET['add'])||$edit))echo '<section class="panel form-panel"><div class="panel-head"><h3>'.($edit?'Edit kategori':'Kategori baru').'</h3><a class="close-link" href="?page=categories">✕</a></div><form class="form-grid" method="post" action="?page=category_save"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div><label>Nama kategori *</label><input name="name" required value="'.e($edit['name']??'').'"></div><div><label>Deskripsi</label><input name="description" value="'.e($edit['description']??'').'"></div><div class="form-actions"><button class="btn primary">Simpan</button><a class="btn ghost" href="?page=categories">Batal</a></div></form></section>';echo '<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nama kategori</th><th>Deskripsi</th><th>Jumlah produk</th>';if(is_admin())echo '<th>Aksi</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr><td><b>'.e($r['name']).'</b></td><td>'.e($r['description']?:'—').'</td><td>'.(int)$r['total_products'].' produk</td>';if(is_admin())echo '<td><div class="actions"><a class="icon-btn" href="?page=categories&edit='.(int)$r['id'].'">✎</a><form method="post" action="?page=category_delete" onsubmit="return confirm(\'Hapus kategori?\')"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="icon-btn danger-text">⌫</button></form></div></td>';echo '</tr>';}if(!$rows)tableEmpty(is_admin()?4:3);echo '</tbody></table></div></section>';layoutEnd();exit;}

if ($page==='suppliers') {require_login();$rows=$pdo->query('SELECT s.*,COUNT(ps.product_id) total_products FROM suppliers s LEFT JOIN product_suppliers ps ON ps.supplier_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();$edit=null;if(isset($_GET['edit'])&&is_admin()){$s=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}layoutStart('Supplier','suppliers',$flash);echo '<div class="page-actions"><div><h2>Daftar Supplier</h2><p>Kelola mitra pemasok produk.</p></div>';if(is_admin())echo '<a class="btn primary" href="?page=suppliers&add=1">＋ Tambah supplier</a>';echo '</div>';if(is_admin()&&(isset($_GET['add'])||$edit)){echo '<section class="panel form-panel"><div class="panel-head"><h3>'.($edit?'Edit supplier':'Supplier baru').'</h3><a class="close-link" href="?page=suppliers">✕</a></div><form class="form-grid" method="post" action="?page=supplier_save"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div><label>Nama supplier *</label><input name="name" required value="'.e($edit['name']??'').'"></div><div><label>Nomor telepon</label><input name="phone" value="'.e($edit['phone']??'').'"></div><div><label>Email</label><input type="email" name="email" value="'.e($edit['email']??'').'"></div><div><label>Alamat</label><input name="address" value="'.e($edit['address']??'').'"></div><div class="form-actions"><button class="btn primary">Simpan supplier</button><a class="btn ghost" href="?page=suppliers">Batal</a></div></form></section>';}echo '<section class="panel"><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Kontak</th><th>Alamat</th><th>Produk terhubung</th>';if(is_admin())echo '<th>Aksi</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr><td><b>'.e($r['name']).'</b></td><td>'.e($r['phone']?:'—').'<small class="subline">'.e($r['email']?:'').'</small></td><td>'.e($r['address']?:'—').'</td><td>'.(int)$r['total_products'].' produk</td>';if(is_admin())echo '<td><div class="actions"><a class="icon-btn" href="?page=suppliers&edit='.(int)$r['id'].'">✎</a><form method="post" action="?page=supplier_delete" onsubmit="return confirm(\'Hapus supplier?\')"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="icon-btn danger-text">⌫</button></form></div></td>';echo '</tr>';}if(!$rows)tableEmpty(is_admin()?5:4);echo '</tbody></table></div></section>';layoutEnd();exit;}

if ($page==='stock') { $products=$pdo->query('SELECT id,sku,name,stock FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT sm.*,p.name product,p.sku,u.full_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN users u ON u.id=sm.user_id ORDER BY sm.created_at DESC LIMIT 100')->fetchAll();layoutStart('Barang Masuk & Keluar','stock',$flash);echo '<div class="page-actions"><div><h2>Transaksi Stok</h2><p>Setiap perubahan stok akan tercatat pada histori.</p></div></div><section class="panel form-panel"><div class="panel-head"><div><h3>Catat pergerakan stok</h3><p>Barang keluar tidak boleh melebihi stok yang tersedia.</p></div></div><form class="form-grid" method="post" action="?page=movement_save"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><div><label>Jenis transaksi *</label><select name="type"><option value="IN">Barang masuk (+)</option><option value="OUT">Barang keluar (−)</option></select></div><div><label>Produk *</label><select name="product_id" required><option value="">Pilih produk</option>';foreach($products as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['sku'].' — '.$p['name'].' (stok: '.$p['stock'].')').'</option>';echo '</select></div><div><label>Jumlah unit *</label><input type="number" name="quantity" min="1" step="1" required placeholder="Contoh: 10"></div><div><label>Catatan</label><input name="note" maxlength="255" placeholder="Alasan / referensi transaksi"></div><div class="form-actions"><button class="btn primary">Simpan transaksi</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Histori transaksi</h3><p>100 transaksi terbaru</p></div><a class="btn ghost" href="?page=reports">Lihat laporan lengkap</a></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Catatan</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.date('d M Y H:i',strtotime($r['created_at'])).'</td><td><b>'.e($r['product']).'</b><small class="subline">'.e($r['sku']).'</small></td><td><span class="pill '.($r['type']==='IN'?'success':'danger').'">'.($r['type']==='IN'?'Barang masuk':'Barang keluar').'</span></td><td><b>'.($r['type']==='IN'?'+':'−').(int)$r['quantity'].'</b></td><td>'.e($r['full_name']).'</td><td>'.e($r['note']?:'—').'</td></tr>';if(!$rows)tableEmpty(6);echo '</tbody></table></div></section>';layoutEnd();exit; }

if ($page==='reports') { $q=$pdo->query("SELECT p.id,p.sku,p.name,p.stock,p.price,c.name category,COALESCE(SUM(CASE WHEN sm.type='IN' THEN sm.quantity ELSE 0 END),0) total_in,COALESCE(SUM(CASE WHEN sm.type='OUT' THEN sm.quantity ELSE 0 END),0) total_out FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN stock_movements sm ON sm.product_id=p.id GROUP BY p.id,p.sku,p.name,p.stock,p.price,c.name ORDER BY p.name")->fetchAll();$ins=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='IN'")->fetchColumn();$outs=(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE type='OUT'")->fetchColumn();layoutStart('Laporan Inventory','reports',$flash);echo '<div class="page-actions"><div><h2>Laporan Inventory</h2><p>Ringkasan stok dan histori barang masuk/keluar.</p></div><button class="btn primary" onclick="window.print()">⇩ Cetak / Simpan PDF</button></div><div class="stats-grid"><article class="stat-card"><div class="stat-icon green">↓</div><span>Total barang masuk</span><strong>'.number_format($ins).'</strong><small>Seluruh histori</small></article><article class="stat-card"><div class="stat-icon orange">↑</div><span>Total barang keluar</span><strong>'.number_format($outs).'</strong><small>Seluruh histori</small></article><article class="stat-card"><div class="stat-icon blue">▤</div><span>Jenis produk</span><strong>'.count($q).'</strong><small>Produk terdaftar</small></article><article class="stat-card"><div class="stat-icon purple">◈</div><span>Nilai stok</span><strong class="money">'.rupiah(array_sum(array_map(fn($x)=>(int)$x['stock']*(float)$x['price'],$q))).'</strong><small>Stok × harga jual</small></article></div><section class="panel"><div class="panel-head"><div><h3>Laporan per produk</h3><p>Rekap dihitung dari histori transaksi stok.</p></div></div><div class="table-wrap"><table><thead><tr><th>SKU / Produk</th><th>Kategori</th><th>Barang masuk</th><th>Barang keluar</th><th>Stok akhir</th><th>Nilai stok</th></tr></thead><tbody>';foreach($q as $r)echo '<tr><td><b>'.e($r['name']).'</b><small class="subline">'.e($r['sku']).'</small></td><td>'.e($r['category']).'</td><td class="positive">+'.(int)$r['total_in'].'</td><td class="negative">−'.(int)$r['total_out'].'</td><td><b>'.(int)$r['stock'].'</b></td><td>'.rupiah((int)$r['stock']*(float)$r['price']).'</td></tr>';if(!$q)tableEmpty(6);echo '</tbody></table></div></section>';layoutEnd();exit; }

if ($page==='users') {require_admin();$rows=$pdo->query('SELECT id,username,full_name,role,created_at FROM users ORDER BY created_at DESC')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT id,username,full_name,role FROM users WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}layoutStart('Pengguna','users',$flash);echo '<div class="page-actions"><div><h2>Manajemen Pengguna</h2><p>Atur akun dan hak akses admin atau staff.</p></div><a class="btn primary" href="?page=users&add=1">＋ Tambah pengguna</a></div>';if(isset($_GET['add'])||$edit)echo '<section class="panel form-panel"><div class="panel-head"><h3>'.($edit?'Edit pengguna':'Pengguna baru').'</h3><a class="close-link" href="?page=users">✕</a></div><form class="form-grid" method="post" action="?page=user_save"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><div><label>Nama lengkap *</label><input name="full_name" required value="'.e($edit['full_name']??'').'"></div><div><label>Username *</label><input name="username" required value="'.e($edit['username']??'').'"></div><div><label>Role *</label><select name="role"><option value="staff" '.(($edit['role']??'staff')==='staff'?'selected':'').'>Staff</option><option value="admin" '.(($edit['role']??'')==='admin'?'selected':'').'>Admin</option></select></div><div><label>Password '.($edit?'(kosongkan jika tidak diganti)':'*').'</label><input type="password" name="password" '.(!$edit?'required minlength="8"':'').' minlength="8" autocomplete="new-password"></div><div class="form-actions"><button class="btn primary">Simpan pengguna</button><a class="btn ghost" href="?page=users">Batal</a></div></form></section>';echo '<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td><b>'.e($r['full_name']).'</b></td><td>'.e($r['username']).'</td><td><span class="pill '.($r['role']==='admin'?'purple-pill':'blue-pill').'">'.e(ucfirst($r['role'])).'</span></td><td>'.date('d M Y',strtotime($r['created_at'])).'</td><td><div class="actions"><a class="icon-btn" href="?page=users&edit='.(int)$r['id'].'">✎</a><form method="post" action="?page=user_delete" onsubmit="return confirm(\'Hapus pengguna ini?\')"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="icon-btn danger-text" '.((int)$r['id']===$_SESSION['user']['id']?'disabled':'').'>⌫</button></form></div></td></tr>';echo '</tbody></table></div></section>';layoutEnd();exit; }
